InvokeScript:
$reportDir = Join-Path $env:USERPROFILE 'Desktop\MSP-Reports'
if (-not (Test-Path $reportDir)) { New-Item -ItemType Directory -Path $reportDir -Force | Out-Null }
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$since = (Get-Date).AddHours(-24)
foreach ($log in @('System','Application')) {
  $events = Get-WinEvent -FilterHashtable @{ LogName = $log; Level = 1,2; StartTime = $since } -ErrorAction SilentlyContinue
  $out = Join-Path $reportDir "events-$log-$stamp.csv"
  if ($events) {
    $events | Select-Object TimeCreated, Id, LevelDisplayName, ProviderName, Message | Export-Csv -Path $out -NoTypeInformation
    Write-Host "Exported $($events.Count) $log events to $out"
  } else {
    Write-Host "No critical $log events in last 24 hours"
  }
}

# --- Reliability Monitor (perfmon /rel) ---
# Its "Save reliability history" option is GUI-only, so the saved copy is built from the same
# data (Win32_ReliabilityRecords / Win32_ReliabilityStabilityMetrics) that Reliability Monitor reads.
Write-Host ''
Write-Host '--- Reliability Monitor (last 30 days) ---'
$relSince = (Get-Date).AddDays(-30)
$failureSources = @('Application Error', 'Application Hang', 'Windows Error Reporting', 'Microsoft-Windows-WER-SystemErrorReporting', 'EventLog', 'Microsoft-Windows-Kernel-Power')
try {
  $records = @(Get-CimInstance Win32_ReliabilityRecords -ErrorAction Stop | Where-Object { $_.TimeGenerated -ge $relSince } | Sort-Object TimeGenerated -Descending | ForEach-Object {
    $category = if ($failureSources -contains $_.SourceName) { 'Failure' }
      elseif (($_.SourceName -eq 'Microsoft-Windows-WindowsUpdateClient' -and $_.EventIdentifier -eq 20) -or ($_.SourceName -eq 'MsiInstaller' -and $_.EventIdentifier -eq 11708)) { 'Failed install' }
      else { 'Information' }
    [pscustomobject]@{ Time = $_.TimeGenerated; Category = $category; Source = $_.SourceName; EventId = $_.EventIdentifier; Product = $_.ProductName; Message = $_.Message }
  })
} catch {
  Write-Host "Could not read reliability records: $($_.Exception.Message)" -ForegroundColor Red
  $records = @()
}
try {
  $metrics = @(Get-CimInstance Win32_ReliabilityStabilityMetrics -ErrorAction Stop | Where-Object { $_.TimeGenerated -ge $relSince } | Sort-Object TimeGenerated -Descending)
} catch { $metrics = @() }

$failures = @($records | Where-Object Category -eq 'Failure')
$failedInstalls = @($records | Where-Object Category -eq 'Failed install')
if ($metrics.Count) {
  $current = [math]::Round($metrics[0].SystemStabilityIndex, 2)
  $lowest = $metrics | Sort-Object SystemStabilityIndex | Select-Object -First 1
  Write-Host ("Stability index : {0} / 10 now, lowest {1} on {2}" -f $current, [math]::Round($lowest.SystemStabilityIndex, 2), $lowest.TimeGenerated.ToString('yyyy-MM-dd'))
} else {
  Write-Host 'Stability index : not available (the Reliability Analysis task may be disabled on this machine)' -ForegroundColor Yellow
}
Write-Host ("Failures        : {0} ({1} app crashes, {2} app hangs, {3} Windows/shutdown)" -f $failures.Count, @($failures | Where-Object Source -eq 'Application Error').Count, @($failures | Where-Object Source -eq 'Application Hang').Count, @($failures | Where-Object { $_.Source -notin 'Application Error', 'Application Hang' }).Count)
Write-Host ("Failed installs : {0}" -f $failedInstalls.Count)
Write-Host ("Total records   : {0}" -f $records.Count)
if ($failures.Count) {
  Write-Host ''
  Write-Host 'Top failing applications:'
  $failures | Group-Object Product | Sort-Object Count -Descending | Select-Object -First 5 | ForEach-Object { Write-Host ("  {0,3}x  {1}" -f $_.Count, $(if ($_.Name) { $_.Name } else { '(unknown)' })) }
}

if ($records.Count -or $metrics.Count) {
  $csvOut = Join-Path $reportDir "reliability-$stamp.csv"
  $records | Select-Object @{N = 'Time'; E = { $_.Time.ToString('yyyy-MM-dd HH:mm:ss') } }, Category, Source, EventId, Product, Message | Export-Csv -Path $csvOut -NoTypeInformation -Encoding UTF8

  $short = { param($t) if ("$t".Length -gt 400) { "$t".Substring(0, 400) + '...' } else { "$t" } }
  $style = '<style>body{font-family:Segoe UI,Arial,sans-serif;margin:24px;color:#222}h1{font-size:22px}h2{font-size:17px;margin-top:28px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #ccc;padding:4px 6px;text-align:left;vertical-align:top;word-break:break-word}td:first-child{white-space:nowrap}th{background:#eee}</style>'
  $summary = @(
    [pscustomobject]@{ Item = 'Computer'; Value = $env:COMPUTERNAME }
    [pscustomobject]@{ Item = 'Generated'; Value = (Get-Date).ToString('yyyy-MM-dd HH:mm') }
    [pscustomobject]@{ Item = 'Period'; Value = "$($relSince.ToString('yyyy-MM-dd')) to $((Get-Date).ToString('yyyy-MM-dd'))" }
    [pscustomobject]@{ Item = 'Current stability index'; Value = $(if ($metrics.Count) { "$([math]::Round($metrics[0].SystemStabilityIndex, 2)) / 10" } else { 'not available' }) }
    [pscustomobject]@{ Item = 'Failures'; Value = $failures.Count }
    [pscustomobject]@{ Item = 'Failed installs'; Value = $failedInstalls.Count }
    [pscustomobject]@{ Item = 'Total records'; Value = $records.Count })
  $daily = $metrics | Group-Object { $_.TimeGenerated.ToString('yyyy-MM-dd') } | ForEach-Object {
    [pscustomobject]@{ Date = $_.Name; 'Lowest stability index' = [math]::Round(($_.Group | Measure-Object SystemStabilityIndex -Minimum).Minimum, 2) }
  }
  $asRows = { param($list) $list | Select-Object @{N = 'Time'; E = { $_.Time.ToString('yyyy-MM-dd HH:mm') } }, Category, Source, EventId, Product, @{N = 'Message'; E = { & $short $_.Message } } }
  $body = @(
    "<h1>Reliability report - $env:COMPUTERNAME</h1>"
    ($summary | ConvertTo-Html -Fragment)
    '<h2>Failures</h2>'
    $(if ($failures.Count) { & $asRows $failures | ConvertTo-Html -Fragment } else { '<p>No failures recorded.</p>' })
    '<h2>Failed installs</h2>'
    $(if ($failedInstalls.Count) { & $asRows $failedInstalls | ConvertTo-Html -Fragment } else { '<p>No failed installs recorded.</p>' })
    '<h2>Daily stability index</h2>'
    $(if ($daily) { $daily | ConvertTo-Html -Fragment } else { '<p>Not available.</p>' })
    '<h2>All reliability records</h2>'
    $(if ($records.Count) { & $asRows $records | ConvertTo-Html -Fragment } else { '<p>No records.</p>' })
  )
  $htmlOut = Join-Path $reportDir "reliability-$stamp.html"
  ConvertTo-Html -Title "Reliability report - $env:COMPUTERNAME" -Head $style -Body ($body -join "`n") | Out-File -FilePath $htmlOut -Encoding UTF8
  Write-Host ''
  Write-Host "Reliability report saved: $htmlOut"
  Write-Host "Reliability records (CSV) saved: $csvOut"
} else {
  Write-Host 'No reliability data found - nothing saved.' -ForegroundColor Yellow
}

# Only open the GUI when there's a visible desktop (not in session 0 / RMM / service context)
if ((Get-Process -Id $PID).SessionId -ne 0 -and [Environment]::UserInteractive) {
  Start-Process -FilePath "$env:SystemRoot\System32\perfmon.exe" -ArgumentList '/rel'
  Write-Host 'Reliability Monitor opened (perfmon /rel).'
} else {
  Write-Host 'No interactive desktop - skipped opening Reliability Monitor. Open the saved HTML report instead.' -ForegroundColor Yellow
}

$targets = @('8.8.8.8','1.1.1.1','google.com')
$gw = (Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Select-Object -First 1).NextHop
if ($gw) { $targets = @($gw) + $targets }
foreach ($t in $targets) {
  $result = Test-Connection -ComputerName $t -Count 2 -Quiet
  $status = if ($result) { 'OK' } else { 'FAIL' }
  Write-Host "[$status] $t"
}
Write-Host "DNS test: $(Resolve-DnsName google.com -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty IPAddress)"

$reportDir = Join-Path $env:USERPROFILE 'Desktop\MSP-Reports'
$logDir = if ($ScriptRoot) { Join-Path $ScriptRoot 'logs' } else { $null }
# Opening files/folders needs a visible desktop (not session 0 / RMM / service context)
$hasDesktop = (Get-Process -Id $PID).SessionId -ne 0 -and [Environment]::UserInteractive

function Show-TextPaged {
  param([string[]]$Lines, [int]$PageSize = 60)
  if (-not $Lines.Count) { Write-Host '(empty file)'; return }
  for ($i = 0; $i -lt $Lines.Count; $i += $PageSize) {
    $end = [math]::Min($i + $PageSize, $Lines.Count) - 1
    $Lines[$i..$end] | ForEach-Object { Write-Host $_ }
    if ($end -lt $Lines.Count - 1) {
      $more = Read-Host ('-- lines {0}-{1} of {2}: Enter for more, q to stop --' -f ($i + 1), ($end + 1), $Lines.Count)
      if ($more -match '^[Qq]') { return }
    }
  }
}

while ($true) {
  $files = @()
  if (Test-Path $reportDir) { $files += @(Get-ChildItem -Path $reportDir -File -ErrorAction SilentlyContinue | ForEach-Object { [pscustomobject]@{ Source = 'Report'; File = $_ } }) }
  if ($logDir -and (Test-Path $logDir)) { $files += @(Get-ChildItem -Path $logDir -File -ErrorAction SilentlyContinue | ForEach-Object { [pscustomobject]@{ Source = 'Log'; File = $_ } }) }
  $files = @($files | Sort-Object { $_.File.LastWriteTime } -Descending)
  Write-Host ''
  if (-not $files.Count) {
    Write-Host "No reports found in $reportDir." -ForegroundColor Yellow
    Write-Host 'Run Export System Information or Export Critical Event Logs & Reliability Report first.'
    return
  }
  Write-Host "--- Reports ($reportDir) ---"
  for ($i = 0; $i -lt $files.Count; $i++) {
    $f = $files[$i].File
    Write-Host ('  [{0,2}] {1}  {2,-6} {3,8}  {4}' -f ($i + 1), $f.LastWriteTime.ToString('yyyy-MM-dd HH:mm'), $files[$i].Source, ('{0:N1} KB' -f ($f.Length / 1KB)), $f.Name)
  }
  Write-Host ''
  $selection = Read-Host 'Enter a report number to view, O to open the reports folder, or 0 to exit'
  if (-not $selection -or $selection -eq '0') { Write-Host 'Exiting tool.' -ForegroundColor Yellow; return }
  if ($selection -match '^[Oo]$') {
    if ($hasDesktop -and (Test-Path $reportDir)) { Start-Process -FilePath explorer.exe -ArgumentList "`"$reportDir`""; Write-Host "Opened $reportDir" -ForegroundColor Green }
    else { Write-Host "Reports folder: $reportDir" }
    continue
  }
  if ($selection -notmatch '^\d+$' -or [int]$selection -lt 1 -or [int]$selection -gt $files.Count) { Write-Host 'Invalid selection.' -ForegroundColor Yellow; continue }

  $f = $files[[int]$selection - 1].File
  Write-Host ''
  Write-Host ('=== {0}  ({1:N1} KB, {2}) ===' -f $f.Name, ($f.Length / 1KB), $f.LastWriteTime.ToString('yyyy-MM-dd HH:mm')) -ForegroundColor Cyan
  try {
    switch ($f.Extension.ToLowerInvariant()) {
      { $_ -in '.html', '.htm' } {
        if ($hasDesktop) { Invoke-Item -LiteralPath $f.FullName; Write-Host 'Opened in your default browser.' -ForegroundColor Green }
        else { Write-Host "HTML reports need a desktop to view. File: $($f.FullName)" -ForegroundColor Yellow }
        break
      }
      '.csv' {
        $rows = @(Import-Csv -LiteralPath $f.FullName)
        Write-Host "$($rows.Count) row(s). Long columns are cut off here - open in Excel for full text."
        if ($rows.Count) { Show-TextPaged -Lines (($rows | Format-Table -AutoSize | Out-String -Width 220) -split "\r?\n" | Where-Object { $_.Trim() }) }
        break
      }
      default { Show-TextPaged -Lines @(Get-Content -LiteralPath $f.FullName) }
    }
  } catch {
    Write-Host "Could not read $($f.Name): $($_.Exception.Message)" -ForegroundColor Red
    continue
  }
  if ($hasDesktop -and $f.Extension -notin '.html', '.htm') {
    $open = Read-Host 'Open this file in its default app? (y/N)'
    if ($open -match '^[Yy]') { Invoke-Item -LiteralPath $f.FullName; Write-Host 'Opened.' -ForegroundColor Green }
  }
}

$tempfolders = @("C:\Windows\Temp\*", "C:\Windows\Prefetch\*", "C:\Documents and Settings\*\Local Settings\temp\*", "C:\Users\*\Appdata\Local\Temp\*")
$doPath = Join-Path $env:ProgramData 'Microsoft\Windows\DeliveryOptimization\Cache\*'
$targets = @($tempfolders + $doPath)
Write-Host 'Cleaning paths:'
Write-Host ''
foreach ($target in $targets) {
  Write-Host "PATH: $target" -ForegroundColor Cyan
  $files = Get-ChildItem $target -Force -Recurse -ErrorAction SilentlyContinue | Where-Object { -not $_.PSIsContainer }
  $removedBytes = 0
  $removedCount = 0
  foreach ($file in $files) {
    Write-Host "  FILE: $($file.FullName)"
    try {
      $removedBytes += $file.Length
      $removedCount++
      Remove-Item $file.FullName -Force -Recurse -ErrorAction Stop
    } catch {
      Write-Host "  FAILED TO REMOVE: $($file.FullName) - $($_.Exception.Message)" -ForegroundColor Red
    }
  }
  Write-Host "  Removed: $removedCount file(s), $([math]::Round($removedBytes/1MB,2)) MB" -ForegroundColor Green
  Write-Host ''
}

Get-Volume | Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' } | ForEach-Object {
  Write-Host "Optimizing drive $($_.DriveLetter):..."
  Optimize-Volume -DriveLetter $_.DriveLetter -ReTrim -Verbose
}
Write-Host 'Drive optimization complete'

if (-not (Get-Module -ListAvailable PSWindowsUpdate)) {
  Write-Host 'PSWindowsUpdate module not installed. Installing from PowerShell Gallery...'
  try {
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    if (-not (Get-PackageProvider -Name NuGet -ErrorAction SilentlyContinue)) { Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force -Scope CurrentUser | Out-Null }
    Install-Module PSWindowsUpdate -Force -Scope CurrentUser -ErrorAction Stop
    Write-Host 'PSWindowsUpdate installed successfully.' -ForegroundColor Green
  } catch { Write-Host "Failed to install PSWindowsUpdate: $($_.Exception.Message)" -ForegroundColor Red; return }
}
Import-Module PSWindowsUpdate -ErrorAction SilentlyContinue
Get-WindowsUpdate -IsInstalled:$false -ErrorAction SilentlyContinue | Select-Object Title, Size, IsDownloaded | Format-Table -AutoSize | Out-String | Write-Host

Get-BitLockerVolume | Select-Object MountPoint, VolumeStatus, EncryptionPercentage, ProtectionStatus | Format-Table -AutoSize | Out-String | Write-Host
$kp = (Get-BitLockerVolume -MountPoint 'C').KeyProtector | Where-Object { $_.KeyProtectorType -eq 'RecoveryPassword' }
if ($kp) {
  Write-Host ''
  Write-Host 'Recovery Password Protector(s) for C:'
  $kp | Select-Object KeyProtectorId, KeyProtectorType | Format-List | Out-String | Write-Host
  Write-Host 'Recovery password not shown - tool output is saved to the MSP Tool log and transcript.'
  Write-Host 'To view it, check AD/Entra ID/your RMM, or run in a separate (unlogged) elevated session:'
  Write-Host '  manage-bde -protectors -get C: -Type RecoveryPassword'
} else {
  Write-Host ''
  Write-Host 'No RecoveryPassword protector found on C:'
}

$admins = Get-LocalGroupMember -Group 'Administrators' -ErrorAction SilentlyContinue
if (-not $admins) {
  net localgroup Administrators
  return
}
$admins = @($admins)
$localAdmins = @($admins | Where-Object { $_.ObjectClass -eq 'User' -and $_.PrincipalSource -eq 'Local' })
$admins | Select-Object Name, ObjectClass, PrincipalSource | Format-Table -AutoSize | Out-String | Write-Host
Write-Host ''
$answer = Read-Host 'Do you want to reset the password for one of these local administrator accounts? (y/N)'
if ($answer -notmatch '^[Yy]') { return }
if (-not $localAdmins) { Write-Host 'No local user accounts were found in the Administrators group.' -ForegroundColor Yellow; return }
Write-Host ''
for ($i = 0; $i -lt $localAdmins.Count; $i++) {
  Write-Host ("  [{0}] {1}" -f ($i + 1), $localAdmins[$i].Name)
}
Write-Host ''
$choice = Read-Host 'Select the account number to reset'
if (-not $choice) { Write-Host 'Cancelled.' -ForegroundColor Yellow; return }
$index = [int]$choice - 1
if ($index -lt 0 -or $index -ge $localAdmins.Count) { Write-Host 'Invalid selection.' -ForegroundColor Yellow; return }
$userName = $localAdmins[$index].Name
$secure = Read-Host ("Enter new password for {0}" -f $userName) -AsSecureString
if (-not $secure) { Write-Host 'No password entered. Cancelled.' -ForegroundColor Yellow; return }
try {
  $plain = [System.Net.NetworkCredential]::new('', $secure).Password
  $newSecure = ConvertTo-SecureString $plain -AsPlainText -Force
  Set-LocalUser -Name $userName -Password $newSecure -ErrorAction Stop
  Write-Host ("Password updated for {0}" -f $userName) -ForegroundColor Green
} catch {
  Write-Host ("Failed to update password for {0}: {1}" -f $userName, $_.Exception.Message) -ForegroundColor Red
}

$cs = Get-CimInstance Win32_ComputerSystem
Write-Host "Computer Name : $env:COMPUTERNAME"
if ($cs.PartOfDomain) {
  Write-Host "Domain Joined : YES" -ForegroundColor Green
  Write-Host "Domain        : $($cs.Domain)" -ForegroundColor Green
  try {
    if (Test-ComputerSecureChannel) { Write-Host 'Secure Channel: HEALTHY' -ForegroundColor Green }
    else { Write-Host 'Secure Channel: BROKEN - run repair tool or rejoin' -ForegroundColor Red }
  } catch { Write-Host "Secure Channel: ERROR - $($_.Exception.Message)" -ForegroundColor Red }
} else {
  Write-Host "Domain Joined : NO" -ForegroundColor Yellow
  Write-Host "Workgroup     : $($cs.Domain)" -ForegroundColor Yellow
}

$domain = $null
$cs = Get-CimInstance Win32_ComputerSystem
if ($cs.PartOfDomain) { $domain = $cs.Domain }
if (-not $domain) { $domain = $env:USERDNSDOMAIN }
if ($domain) {
  $answer = Read-Host "Enter target domain FQDN, or press Enter to use suggested '$domain'"
  if ($answer) { $domain = $answer }
} else {
  $domain = Read-Host 'Enter target domain FQDN (e.g. corp.contoso.com)'
}
if (-not $domain) { Write-Host 'No domain entered - aborted.' -ForegroundColor Yellow; return }
try {
  $ips = [System.Net.Dns]::GetHostAddresses($domain) | Where-Object AddressFamily -eq 'InterNetwork'
  if (-not $ips) { throw 'no A records' }
  Write-Host "[OK] DNS      : $domain -> $($ips[0].IPAddressToString)" -ForegroundColor Green
} catch {
  Write-Host "[FAIL] DNS    : cannot resolve '$domain'." -ForegroundColor Red
}
try {
  $ctx = New-Object System.DirectoryServices.ActiveDirectory.DirectoryContext([System.DirectoryServices.ActiveDirectory.DirectoryContextType]::Domain, $domain)
  $ad = [System.DirectoryServices.ActiveDirectory.Domain]::GetDomain($ctx)
  $dc = $ad.DomainControllers | Select-Object -First 1
  Write-Host "[OK] DC found : $($dc.Name)" -ForegroundColor Green
  $tcp = New-Object System.Net.Sockets.TcpClient
  if (-not $tcp.ConnectAsync($dc.IPAddress, 389).Wait(5000)) { throw "LDAP timeout on $($dc.IPAddress)" }
  $tcp.Close()
  Write-Host "[OK] LDAP     : $($dc.IPAddress):389 reachable" -ForegroundColor Green
  Write-Host ''
  Write-Host "SUCCESS: Workstation can reach domain '$domain'." -ForegroundColor Green
} catch {
  Write-Host "[FAIL] AD/LDAP : $($_.Exception.Message)" -ForegroundColor Red
  $vpns = @()
  try { $vpns = Get-VpnConnection -AllUserConnection -ErrorAction SilentlyContinue } catch { }
  try { $vpns += Get-VpnConnection -ErrorAction SilentlyContinue } catch { }
  $vpns = @($vpns | Sort-Object Name -Unique)
  if ($vpns.Count) {
    Write-Host ''
    Write-Host 'VPN connections found on this workstation:' -ForegroundColor Yellow
    for ($i = 0; $i -lt $vpns.Count; $i++) { Write-Host ("  [{0}] {1} ({2})" -f ($i + 1), $vpns[$i].Name, $vpns[$i].ConnectionStatus) }
    $choice = Read-Host 'Enter VPN number to start, or press Enter to skip'
    if ($choice) {
      $idx = [int]$choice - 1
      if ($idx -ge 0 -and $idx -lt $vpns.Count) {
        $vpnName = $vpns[$idx].Name
        try {
          if ($vpns[$idx].PSTypeNames -match 'AllUser') { rasdial "$vpnName" } else { Start-VpnConnection -Name $vpnName -PassThru -ErrorAction Stop | Out-Null }
          Write-Host "[OK] VPN started: $vpnName" -ForegroundColor Green
          $run = Read-Host 'Run Domain Connectivity Test again now? (Y/n)'
          if ($run -notmatch '^[Nn]') { & $MyInvocation.MyCommand.ScriptBlock }
        } catch { Write-Host "[FAIL] VPN start failed: $($_.Exception.Message)" -ForegroundColor Red }
      }
    }
  } else { Write-Host 'No VPN connections found on this workstation.' -ForegroundColor Yellow }
}

$vpns = @()
try { $vpns = Get-VpnConnection -AllUserConnection -ErrorAction SilentlyContinue } catch { }
try { $vpns += Get-VpnConnection -ErrorAction SilentlyContinue } catch { }
$vpns = @($vpns | Sort-Object Name -Unique)
if (-not $vpns.Count) { Write-Host 'No VPN connections found on this workstation.' -ForegroundColor Yellow; return }
Write-Host 'VPN connections found:'
for ($i = 0; $i -lt $vpns.Count; $i++) { Write-Host ("  [{0}] {1} ({2})" -f ($i + 1), $vpns[$i].Name, $vpns[$i].ConnectionStatus) }
$choice = Read-Host 'Enter VPN number to start'
if (-not $choice) { Write-Host 'Cancelled.' -ForegroundColor Yellow; return }
$idx = [int]$choice - 1
if ($idx -lt 0 -or $idx -ge $vpns.Count) { Write-Host 'Invalid selection.' -ForegroundColor Yellow; return }
$vpnName = $vpns[$idx].Name
try {
  if ($vpns[$idx].PSTypeNames -match 'AllUser') {
    rasdial "$vpnName"
  } else {
    Start-VpnConnection -Name $vpnName -PassThru -ErrorAction Stop | Out-Null
  }
  Write-Host "[OK] VPN started: $vpnName" -ForegroundColor Green
  $run = Read-Host 'Run Domain Connectivity Test now? (Y/n)'
  if ($run -notmatch '^[Nn]') { Write-Host 'Run the Domain Connectivity Test tool next.' -ForegroundColor Yellow }
} catch {
  Write-Host "[FAIL] VPN start failed: $($_.Exception.Message)" -ForegroundColor Red
}

$domain = Read-Host 'Enter target domain FQDN (e.g. corp.contoso.com)'
if (-not $domain) { Write-Host 'No domain entered - aborted.' -ForegroundColor Yellow; return }
$cred = Get-Credential -Message "Enter the account you want to test against $domain"
if (-not $cred) { Write-Host 'Credentials required - aborted.' -ForegroundColor Yellow; return }
try {
  $ctx = New-Object System.DirectoryServices.ActiveDirectory.DirectoryContext([System.DirectoryServices.ActiveDirectory.DirectoryContextType]::Domain, $domain, $cred.UserName, $cred.GetNetworkCredential().Password)
  $ad = [System.DirectoryServices.ActiveDirectory.Domain]::GetDomain($ctx)
  Write-Host "SUCCESS: Credential validated for domain '$($ad.Name)'." -ForegroundColor Green
} catch {
  Write-Host "FAILED: Credential did not validate for domain '$domain'. $($_.Exception.Message)" -ForegroundColor Red
}

$vpns = @()
try { $vpns += Get-VpnConnection -AllUserConnection -ErrorAction SilentlyContinue } catch { }
try { $vpns += Get-VpnConnection -ErrorAction SilentlyContinue } catch { }
$vpns = @($vpns | Sort-Object Name -Unique)
if (-not $vpns.Count) { Write-Host 'No VPN connections found on this workstation.' -ForegroundColor Yellow; return }
Write-Host 'Visible VPN connections:'
for ($i = 0; $i -lt $vpns.Count; $i++) {
  $state = if ($vpns[$i].ConnectionStatus) { $vpns[$i].ConnectionStatus } else { 'Unknown' }
  Write-Host ("  [{0}] {1} ({2})" -f ($i + 1), $vpns[$i].Name, $state)
}
Write-Host ''
$choice = Read-Host 'Enter VPN number to start'
if (-not $choice) { Write-Host 'Cancelled.' -ForegroundColor Yellow; return }
$idx = [int]$choice - 1
if ($idx -lt 0 -or $idx -ge $vpns.Count) { Write-Host 'Invalid selection.' -ForegroundColor Yellow; return }
$vpnName = $vpns[$idx].Name
try {
  $current = $vpns[$idx].ConnectionStatus
  if ($current -eq 'Connected') {
    Write-Host "[OK] VPN already connected: $vpnName" -ForegroundColor Green
    return
  }
  rasdial "$vpnName"
  Write-Host "[OK] VPN start command sent: $vpnName" -ForegroundColor Green
} catch {
  Write-Host "[FAIL] VPN start failed: $($_.Exception.Message)" -ForegroundColor Red
}

Write-Host 'Running gpupdate /force...'
gpupdate /force
Write-Host ''
Write-Host 'Applied Group Policy results:'
try {
  gpresult /r
} catch {
  Write-Host "gpresult failed: $($_.Exception.Message)" -ForegroundColor Red
}

$cs = Get-CimInstance Win32_ComputerSystem
if ($cs.PartOfDomain) { Write-Host "Already joined to '$($cs.Domain)'. Nothing to do." -ForegroundColor Yellow; return }
$domain = Read-Host 'Enter target domain FQDN (e.g. corp.contoso.com)'
if (-not $domain) { Write-Host 'No domain entered - aborted.' -ForegroundColor Yellow; return }
try {
  $ctx = New-Object System.DirectoryServices.ActiveDirectory.DirectoryContext([System.DirectoryServices.ActiveDirectory.DirectoryContextType]::Domain, $domain)
  [void][System.DirectoryServices.ActiveDirectory.Domain]::GetDomain($ctx)
  Write-Host "[OK] Domain reachable: $domain" -ForegroundColor Green
} catch { Write-Host "Cannot reach domain '$domain': $($_.Exception.Message)" -ForegroundColor Red; return }
$cred = Get-Credential -Message "Account with rights to join $domain"
if (-not $cred) { Write-Host 'Credentials required - aborted.' -ForegroundColor Yellow; return }
$ou = Read-Host 'Target OU path (optional, press Enter to skip, e.g. OU=Workstations,DC=corp,DC=contoso,DC=com)'
$params = @{ DomainName = $domain; Credential = $cred; Force = $true; ErrorAction = 'Stop' }
if ($ou) { $params['OU'] = $ou }
try {
  Add-Computer @params
  Write-Host "SUCCESS: Joined domain '$domain'. A restart is required to finish." -ForegroundColor Green
  $r = Read-Host 'Restart now? (Y/n)'
  if ($r -notmatch '^n') { Restart-Computer -Force } else { Write-Host 'Reboot later to complete the join.' -ForegroundColor Yellow }
} catch { Write-Host "FAILED to join domain: $($_.Exception.Message)" -ForegroundColor Red }

$cs = Get-CimInstance Win32_ComputerSystem
if (-not $cs.PartOfDomain) { Write-Host 'Workstation is not domain joined.' -ForegroundColor Yellow; return }
Write-Host "Current domain: $($cs.Domain)"
$confirm = Read-Host 'Type YES to remove this workstation from the domain'
if ($confirm -ne 'YES') { Write-Host 'Cancelled.' -ForegroundColor Yellow; return }
$workgroup = Read-Host 'Enter workgroup name to join (default: WORKGROUP)'
if (-not $workgroup) { $workgroup = 'WORKGROUP' }
$cred = Get-Credential -Message 'Enter domain account with rights to remove this computer from the domain'
if (-not $cred) { Write-Host 'Credentials required - aborted.' -ForegroundColor Yellow; return }
$stageOnly = Read-Host 'Stage the unjoin without restarting now? (Y/n)'
try {
  Remove-Computer -UnjoinDomainCredential $cred -WorkgroupName $workgroup -Force -ErrorAction Stop
  Write-Host "SUCCESS: Removed from domain and joined workgroup '$workgroup'. Restart is required." -ForegroundColor Green
  if ($stageOnly -match '^[Yy]') {
    Write-Host 'Unjoin staged. Reboot later to complete the change.' -ForegroundColor Yellow
    return
  }
  $r = Read-Host 'Restart now? (Y/n)'
  if ($r -notmatch '^n') { Restart-Computer -Force } else { Write-Host 'Reboot later to complete the unjoin.' -ForegroundColor Yellow }
} catch {
  Write-Host "FAILED to remove workstation from domain: $($_.Exception.Message)" -ForegroundColor Red
}

$cs = Get-CimInstance Win32_ComputerSystem
if (-not $cs.PartOfDomain) { Write-Host 'Workstation is not domain joined.' -ForegroundColor Yellow; return }
Write-Host "Testing secure channel for domain '$($cs.Domain)'..."
if (Test-ComputerSecureChannel) {
  Write-Host 'Secure channel is HEALTHY - no repair needed.' -ForegroundColor Green
} else {
  Write-Host 'Secure channel is BROKEN - repairing...' -ForegroundColor Yellow
  if (Test-ComputerSecureChannel -Repair) {
    Write-Host 'Secure channel repaired successfully.' -ForegroundColor Green
    $r = Read-Host 'Restart now? (Y/n)'
    if ($r -notmatch '^n') { Restart-Computer -Force }
  } else {
    Write-Host 'Repair failed - leave and rejoin the domain instead.' -ForegroundColor Red
  }
}

$issues = @()
